// Explicit materialization gives project-local read-only audio an independent file destination.
void saveEmbeddedAudioAs526(){auto identity=p.getAudio();if(!identity||!identity->embedded526)return;if(p.multiMode){saveMultiDialog();return;}auto generation=p.loadGeneration.load();auto file=juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile(juce::File(identity->path).getFileNameWithoutExtension()+".wav");chooser=std::make_unique<juce::FileChooser>("Save embedded source audio as",file,"*.wav",true);auto safe=SafePointer<Editor>(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,identity,generation](const juce::FileChooser& dialog){if(!safe||dialog.getResult()==juce::File())return;auto destination=dialog.getResult().withFileExtension("wav");if(!LibraryStore::editable(destination)){safe->tell("Choose a writable destination in your own library.");return;}safe->tell("Saving embedded source audio...");safe->browserEditPool.addJob([safe,identity,generation,destination]{bool ok=PortableMedia526::writeWave(destination,*identity);auto hash=ok?LibraryStore::fingerprint(destination):juce::String();auto alias=ok?PortableMedia526::movedAlias(identity,destination,hash):nullptr;juce::MessageManager::callAsync([safe,identity,generation,alias,ok]{if(!safe)return;if(ok&&alias){const juce::ScopedLock guard(safe->p.lock);if(safe->p.audio==identity&&safe->p.loadGeneration==generation){safe->p.audio=alias;safe->p.loadedParameterAudio=alias;safe->p.hasSavedConfig=false;safe->p.edited(false);safe->p.resetHistory();safe->refresh();}}safe->tell(ok?"Source audio saved independently.":"Could not save source audio.");});});});}
